  detail.innerHTML = `<strong>${emoji} ${name} · ${count}</strong>${description}`;
  if (type === 'heal') {
    const b = document.createElement('button');
    b.className = 'btn primary';
    b.style.marginTop = '8px';
    b.textContent = 'Usar';
    b.disabled = !count || hero.hp === hero.maxHp;
    b.onclick = () => {
      if (!hero.inventory[icon] || hero.hp === hero.maxHp) return;
      hero.inventory[icon]--;
      hero.hp = Math.min(hero.maxHp, hero.hp + (icon === '🍎' ? 6 : 10));
