/* ── screen-space atmosphere ───────────────────────────────────────────── */
function drawLightRays() {
  const strength = isNight() ? 0.035 : 0.085;
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  for (let i = 0; i < 4; i++) {
    const x = ((i * 73 + clock * 2.4) % (SW + 130)) - 65;
    const g = ctx.createLinearGradient(x, 0, x + 80, SH);
    g.addColorStop(0, `rgba(255,229,166,${strength})`);
    g.addColorStop(0.45, `rgba(255,218,140,${strength * 0.45})`);
    g.addColorStop(1, 'rgba(255,218,140,0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.moveTo(x, 0); ctx.lineTo(x + 20, 0); ctx.lineTo(x + 86, SH); ctx.lineTo(x + 48, SH);
    ctx.closePath(); ctx.fill();
  }
  ctx.restore();
}
function drawAmbient() {
  const night = isNight();
  const autumn = mode === 'world' && hero.x / T > 62;
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  for (let i = 0; i < 28; i++) {
    const speed = 4 + (i % 4) * 2;
    const px = ((i * 97 + clock * speed) % (SW + 30)) - 15;
    const py = ((i * 53 + Math.sin(clock * 0.8 + i) * 13 + clock * (night ? 2 : 5)) % (SH + 30)) - 15;
    const a = (night ? 0.55 : 0.2) * (0.45 + 0.55 * Math.sin(clock * 2 + i));
    if (a <= 0.02) continue;
    ctx.globalAlpha = a;
    ctx.fillStyle = night ? '#b9e4ff' : autumn ? '#ffc77a' : '#ffe6a8';
    ctx.beginPath(); ctx.arc(px, py, 0.6 + (i % 3) * 0.35, 0, 7); ctx.fill();
  }
  if (mode === 'dungeon') {
    for (let i = 0; i < 14; i++) {
      const px = 18 + ((i * 41 + clock * 6) % (SW - 36));
      const py = SH - ((i * 29 + clock * 11) % (SH - 40));
      ctx.globalAlpha = 0.18 + 0.12 * Math.sin(clock * 3 + i);
      ctx.fillStyle = '#ffbf7a';
      ctx.fillRect(px, py, 1, 1);
    }
  }
  ctx.restore();
}

/* ── cinematic post-processing ─────────────────────────────────────────── */
function drawPost() {
  const w = canvas.width, h = canvas.height;
  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);

  // bloom
  fx.g.clearRect(0, 0, w, h);
  fx.g.filter = 'blur(5px)';
  fx.g.drawImage(canvas, 0, 0);
  fx.g.filter = 'none';
  ctx.globalCompositeOperation = 'screen';
  ctx.globalAlpha = 0.16;
  ctx.drawImage(fx.c, 0, 0);

  // depth of field at the edges
  dof.g.clearRect(0, 0, w, h);
  dof.g.filter = 'blur(2.6px)';
  dof.g.drawImage(canvas, 0, 0);
  dof.g.filter = 'none';
  dof.g.globalCompositeOperation = 'destination-in';
  const dg = dof.g.createRadialGradient(w / 2, h / 2, h * 0.4, w / 2, h / 2, h * 0.82);
  dg.addColorStop(0, 'rgba(0,0,0,0)');
  dg.addColorStop(0.68, 'rgba(0,0,0,.18)');
  dg.addColorStop(1, 'rgba(0,0,0,.72)');
  dof.g.fillStyle = dg;
  dof.g.fillRect(0, 0, w, h);
  dof.g.globalCompositeOperation = 'source-over';
  ctx.globalCompositeOperation = 'source-over';
  ctx.globalAlpha = 0.52;
  ctx.drawImage(dof.c, 0, 0);

  // warm/cool grade
  ctx.globalCompositeOperation = 'overlay';
  ctx.globalAlpha = 0.12;
  const lg = ctx.createLinearGradient(0, 0, 0, h);
  lg.addColorStop(0, '#ffd89a');
  lg.addColorStop(0.55, '#7ab8a4');
  lg.addColorStop(1, '#102536');
  ctx.fillStyle = lg;
  ctx.fillRect(0, 0, w, h);

  // night wash
  if (isNight()) {
    ctx.globalCompositeOperation = 'source-over';
    ctx.globalAlpha = 0.15;
    ctx.fillStyle = '#0a1a3a';
    ctx.fillRect(0, 0, w, h);
  }

  // vignette
  ctx.globalCompositeOperation = 'source-over';
  ctx.globalAlpha = 1;
  const vg = ctx.createRadialGradient(w / 2, h / 2, h * 0.34, w / 2, h / 2, h * 0.78);
  vg.addColorStop(0, 'rgba(0,0,0,0)');
  vg.addColorStop(0.72, 'rgba(0,0,0,.08)');
  vg.addColorStop(1, 'rgba(0,0,0,.58)');
  ctx.fillStyle = vg;
  ctx.fillRect(0, 0, w, h);

  if (flash > 0) {
    ctx.fillStyle = `rgba(255,74,58,${flash * 0.5})`;
    ctx.fillRect(0, 0, w, h);
  }
  if (whiteFlash > 0) {
    ctx.fillStyle = `rgba(255,238,178,${whiteFlash * 0.4})`;
    ctx.fillRect(0, 0, w, h);
  }
  ctx.restore();
}

/* ── quest compass ─────────────────────────────────────────────────────── */
function drawCompass() {
  if (!started) return;
  const target = questTarget();
  if (!target) return;
  const camX = mode === 'world' ? Math.round(cam.x) : 0;
  const camY = mode === 'world' ? Math.round(cam.y) : 0;
  const tx = target.x - camX, ty = target.y - camY;
  const onScreen = tx > 12 && tx < SW - 12 && ty > 12 && ty < SH - 12;
  ctx.save();
  ctx.globalAlpha = 0.95;
  if (onScreen) {
    const bob = Math.sin(clock * 4) * 1.2;
    ctx.save();
    ctx.translate(tx, ty - 25 + bob);
    ctx.rotate(Math.PI / 4);
    ctx.fillStyle = '#f1d782';
    ctx.fillRect(-2, -2, 4, 4);
    ctx.fillStyle = 'rgba(241,215,130,.22)';
    ctx.fillRect(-4, -4, 8, 8);
    ctx.restore();
    text(target.label, tx - target.label.length * 1.45, ty - 31 + bob, '#ffe9a8', 5);
  } else {
    const ang = Math.atan2(ty - SH / 2, tx - SW / 2);
    const ex = clamp(tx, 11, SW - 11), ey = clamp(ty, 11, SH - 11);
    ctx.save();
    ctx.translate(ex, ey);
    ctx.rotate(ang);
    ctx.fillStyle = '#f1d782';
    ctx.beginPath(); ctx.moveTo(5, 0); ctx.lineTo(-3, -4); ctx.lineTo(-3, 4); ctx.closePath(); ctx.fill();
    ctx.restore();
    const dt = Math.round(Math.hypot(hero.x - target.x, hero.y - target.y) / T);
    text(`${dt}m`, ex - 5, ey + 9, '#e9d99a', 5);
  }
  ctx.restore();
}

/* ── animated dialogue portrait ────────────────────────────────────────── */
function drawPortrait() {
  const c = $('dialogPortrait');
