```
function drawAvatar() {
  const c = $('heroAvatar');
  if (!c || !heroSprites) return;
  const g = c.getContext('2d');
  g.imageSmoothingEnabled = false;
  g.clearRect(0,0,c.width,c.height);
  // backdrop
  const bg = g.createRadialGradient(38,42,6,38,56,62);
  bg.addColorStop(0,'#6f8a5c'); bg.addColorStop(.5,'#33492f'); bg.addColorStop(1,'#101b16');
  g.fillStyle=bg; g.fillRect(0,0,c.width,c.height);
  // moon glow
  g.save(); g.globalCompositeOperation='lighter';
  const gl=g.createRadialGradient(38,26,2,38,30,34);
  gl.addColorStop(0,'rgba(255,235,170,.35)'); gl.addColorStop(1,'rgba(255,235,170,0)');
  g.fillStyle=gl; g.fillRect(0,0,c.width,c.height); g.restore();
  // pedestal
  g.fillStyle='rgba(10,20,14,.35)'; g.beginPath(); g.ellipse(38,101,20,5,0,0,7); g.fill();
  const bob = Math.sin(clock*1.8)*1.2;
  const img = heroSprites.S.idle[Math.floor(clock*2)%2];
  g.drawImage(img, 8, 8+bob, 60, 90);
  // gold frame line
  g.strokeStyle='rgba(231,212,141,.25)'; g.strokeRect(.5,.5,c.width-1,c.height-1);
}
