function drawAvatar() {
  const c = $('heroAvatar');
  if (!c || !heroSprites) return;
  const g = c.getContext('2d');
  g.imageSmoothingEnabled = false;
  g.clearRect(0, 0, c.width, c.height);
  const bg = g.createRadialGradient(38, 38, 4, 38, 58, 66);
  bg.addColorStop(0, '#6f8a5c');
  bg.addColorStop(0.45, '#33492f');
  bg.addColorStop(1, '#0d1712');
  g.fillStyle = bg;
  g.fillRect(0, 0, c.width, c.height);
  g.save();
  g.globalCompositeOperation = 'lighter';
  const halo = g.createRadialGradient(38, 24, 2, 38, 30, 36);
  halo.addColorStop(0, 'rgba(255,235,170,.34)');
  halo.addColorStop(1, 'rgba(255,235,170,0)');
  g.fillStyle = halo;
  g.fillRect(0, 0, c.width, c.height);
  g.restore();
  g.fillStyle = 'rgba(8,16,12,.4)';
  g.beginPath(); g.ellipse(38, 101, 20, 5, 0, 0, 7); g.fill();
  const bob = Math.sin(clock * 1.8) * 1.2;
  const img = heroSprites.S.idle[Math.floor(clock * 2) % 2];
  g.drawImage(img, 8, 8 + bob, 60, 90);
  g.strokeStyle = 'rgba(231,212,141,.22)';
  g.strokeRect(0.5, 0.5, c.width - 1, c.height - 1);
}

