function drawNPC2(x, y) {
  if (started) npc2.facing = dir8(hero.x - x, hero.y - y);
  const talking = !$('dialogOverlay').classList.contains('hidden') && dialogKey === 'bruma';
  const state = talking ? 'talk' : 'idle';
  const frames = spiritSprites[npc2.facing][state];
  const idx = Math.floor(clock * (talking ? 5 : 2)) % frames.length;
  const float = Math.sin(clock * 1.7) * 1.6;
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  glow(x, y - 10 + float, 16, '#8ff0dc', 0.16 + Math.sin(clock * 2.4) * 0.04);
  ctx.restore();
  shadow(x, y + 5, 6, 2, 0.24);
  ctx.save();
  ctx.globalAlpha = 0.95;
  ctx.drawImage(frames[idx], Math.round(x - 8), Math.round(y - 20 + float), 16, 24);
  ctx.restore();
  if (talking) speechBubble(x, y - 24 + float);
  else {
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    for (let i = 0; i < 3; i++) {
      const a = clock * 0.9 + i * 2.1;
      ctx.globalAlpha = 0.3 + 0.3 * Math.sin(clock * 2 + i);
      ctx.fillStyle = '#c8fff2';
      ctx.fillRect(x + Math.cos(a) * (8 + i * 2), y - 12 + float + Math.sin(a * 1.4) * 5, 1, 1);
    }
