    p(g, hx - 5, hy + 3, 10, 1, pal.hairDark);
    p(g, hx - 3, hy + 6, 2, 1, pal.hairDark);
    p(g, hx + 1, hy + 6, 2, 1, pal.hairDark);
    if (side) {
      const ex = hx + side * 2;
      p(g, ex, hy + 7, 2, 3, pal.white);
      p(g, ex + (side > 0 ? 1 : 0), hy + 7, 1, 2, pal.eye);
      p(g, ex - 1, hy + 11, 3, 1, talk ? pal.mouth : pal.skinShade);
      p(g, hx + side, hy + 10, 1, 1, pal.skinShade);
    } else {
      p(g, hx - 3, hy + 7, 2, 3, pal.white);
      p(g, hx + 1, hy + 7, 2, 3, pal.white);
      p(g, hx - 2, hy + 8, 1, 2, pal.eye);
      p(g, hx + 2, hy + 8, 1, 2, pal.eye);
      p(g, hx - 1, hy + 10, 1, 1, pal.skinShade);
      if (talk) p(g, hx - 1, hy + 11, 3, 1, pal.mouth);
      else p(g, hx - 1, hy + 11, 2, 1, pal.skinShade);
      p(g, hx - 4, hy + 9, 1, 1, pal.skinShade);
      p(g, hx + 4, hy + 9, 1, 1, pal.skinShade);
