  const goldD = pal.goldDark || shade(pal.gold, -0.28);
  const longHair = pal.longHair !== false;

  g.save();
  g.translate(lean, -bob);

  drawCape(g, pal, dir, state, f, cx);

  /* long hair falling behind the body */
  if (longHair && !back) {
