1447: /* ── world rules ───────────────────────────────────────────────────────── */
1448: const DIRV = { S: [0, 1], SE: [0.7, 0.7], E: [1, 0], NE: [0.7, -0.7], N: [0, -1], NW: [-0.7, -0.7], W: [-1, 0], SW: [-0.7, 0.7] };
