1450: function pathTile(x, y) {
1451:   return (x >= 12 && x <= 14 && y >= 9 && y <= 29) ||
1452:     (y >= 27 && y <= 29 && x >= 11 && x <= 50) ||
1453:     (y >= 27 && y <= 29 && x >= 49 && x <= 84) ||
1454:     (x >= 80 && x <= 82 && y >= 14 && y <= 29) ||
1455:     (y >= 21 && y <= 23 && x >= 67 && x <= 81);
1456: }
1457: function isWater(x, y) { return x >= 51 && x <= 55 && y >= 12 && y <= 43; }
1458: function isBridge(x, y) { return x >= 51 && x <= 55 && y >= 27 && y <= 29; }
1459: function treeTile(x, y) {
1460:   if (x < 1 || y < 1 || x >= W - 1 || y >= H - 1) return false;
1461:   if (pathTile(x, y)) return false;
1462:   if (x >= 50 && x <= 56 && y >= 11 && y <= 44) return false;
1463:   if (Math.hypot(x - 12, y - 12) < 4 || Math.hypot(x - 17, y - 22) < 2.5 || Math.hypot(x - 48, y - 31) < 3) return false;
1464:   if (Math.hypot(x - 82, y - 14) < 3 || Math.hypot(x - 74, y - 22) < 3.5 || Math.hypot(x - 66, y - 20) < 3.5) return false;
1465:   const ds = Math.hypot(x - 12, y - 12);
1466:   if (ds < 5.5) return false;
1467:   if (ds < 9 && rand(x * 3 + 1, y * 5 + 2) > 0.72) return true;
1468:   const clump = rand(Math.floor(x / 4) * 7 + 3, Math.floor(y / 4) * 11 + 5);
1469:   let threshold = clump > 0.58 ? 0.9 : 0.948;
1470:   if (y > 53 || x > 62) threshold -= 0.012;
1471:   return rand(x, y) > threshold;
1472: }
1473: function blocked(x, y) {
1474:   if (mode === 'dungeon') return x < 13 || x > SW - 13 || y < 20 || y > SH - 13;
1475:   if (x < 5 || y < 5 || x > W * T - 5 || y > H * T - 5) return true;
1476:   const tx = Math.floor(x / T), ty = Math.floor((y + 3) / T);
1477:   if (treeTile(tx, ty)) return true;
1478:   if (isWater(tx, ty) && !isBridge(tx, ty)) return true;
1479:   if (Math.hypot(x - shrine.x, y - shrine.y) < 7) return true;
1480:   return false;
1481: }
1482: function dir8(dx, dy) {
1483:   if (!dx && !dy) return hero.facing;
1484:   const a = Math.atan2(dy, dx);
1485:   const i = Math.round(a / (Math.PI / 4));
1486:   return ['E', 'SE', 'S', 'SW', 'W', 'NW', 'N', 'NE'][(i + 8) % 8];
1487: }
